//! The Salsa database: source files are its inputs, and every analysis is a query over them.
//!
//! The constructors, getters and setters below are generated by Salsa's macros, which do not
//! carry documentation; the structs and fields say what they are.
#![allow(missing_docs)]

/// A source file: the root input of every query.
#[salsa::input]
pub struct SourceFile {
    /// The file's path, as shown in diagnostics.
    #[returns(ref)]
    pub path: String,
    /// The file's text.
    #[returns(ref)]
    pub text: String,
}

/// Something with a body: a function or a test, by its position among the file's items of that
/// kind.
#[salsa::interned]
pub struct Owner<'db> {
    /// The file the item is in.
    #[returns(copy)]
    pub file: SourceFile,
    /// Which item.
    #[returns(copy)]
    pub item: Item,
}

/// A function or a test, by its index in the file's [`ItemTree`](crate::ItemTree).
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash, PartialOrd, Ord)]
pub enum Item {
    /// `fn`.
    Fn(u32),
    /// `test`.
    Test(u32),
}

/// The queries `moddil-sema` defines need a database implementing this.
#[salsa::db]
pub trait Db: salsa::Database {}

/// The database: holds the inputs and memoises every query.
#[salsa::db]
#[derive(Clone, Default)]
pub struct Database {
    storage: salsa::Storage<Self>,
}

#[salsa::db]
impl salsa::Database for Database {}

#[salsa::db]
impl Db for Database {}
